// React
import { useMemo, useState } from "react";

// Third Party
import { BaseModal, BaseTable, ModalSize } from "aa-geuthur-react";
import { Plus, Trash2, Users2 } from "lucide-react";
import { Button, Card, Form, Spinner } from "react-bootstrap";
import { useTranslation } from "react-i18next";

// AA TaxSystem
import type { components } from "@/Api/OpenApi";
import {
  useAvailableGroups,
  useGroupActions,
  useGroups,
} from "@/Components/OwnerManage/Hooks";
import { getGroupColumns } from "@/Components/Tables";

interface GroupsTabProps {
  ownerId: number;
}

type GroupManagementRow = components["schemas"]["GroupManagementSchema"];

export function GroupsTab({ ownerId }: GroupsTabProps) {
  const { t } = useTranslation();

  // Create Group Modal State
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newGroupName, setNewGroupName] = useState("");
  const [selectedAuthGroupIds, setSelectedAuthGroupIds] = useState<number[]>([]);
  const [authGroupSearch, setAuthGroupSearch] = useState("");

  // Delete Group Modal State
  const [groupToDelete, setGroupToDelete] = useState<GroupManagementRow | null>(null);
  const [deleteComment, setDeleteComment] = useState("");

  const { data: groups, isLoading, isError } = useGroups(ownerId);
  const { data: availableGroups, isLoading: availableLoading } = useAvailableGroups(
    ownerId,
    showCreateModal,
  );
  const groupActions = useGroupActions(ownerId, {
    onCreated: () => {
      setShowCreateModal(false);
      setNewGroupName("");
      setSelectedAuthGroupIds([]);
      setAuthGroupSearch("");
    },
    onDeleted: () => {
      setGroupToDelete(null);
      setDeleteComment("");
    },
  });

  const toggleAuthGroup = (groupId: number) => {
    setSelectedAuthGroupIds((prev) =>
      prev.includes(groupId) ? prev.filter((id) => id !== groupId) : [...prev, groupId],
    );
  };

  const filteredAvailableGroups = useMemo(() => {
    if (!availableGroups) return [];
    if (!authGroupSearch.trim()) return availableGroups;
    const q = authGroupSearch.toLowerCase();
    return availableGroups.filter((g) => g.name.toLowerCase().includes(q));
  }, [availableGroups, authGroupSearch]);

  const columns = useMemo(
    () =>
      getGroupColumns({
        t,
        onDelete: (group) => {
          setGroupToDelete(group);
          setDeleteComment(t("Deleted via Tax System"));
        },
      }),
    [t],
  );

  return (
    <div className="mt-3">
      <Card className="bg-dark border-secondary">
        <Card.Header className="d-flex flex-wrap align-items-center justify-content-between gap-2 border-secondary">
          <h5 className="mb-0 d-flex align-items-center gap-2">
            <Users2 size={18} className="text-primary" />
            {t("Tax Groups")}
          </h5>
          <Button
            variant="primary"
            size="sm"
            onClick={() => setShowCreateModal(true)}
          >
            <Plus size={14} />
            {t("Add Tax-Free Group")}
          </Button>
        </Card.Header>
        <Card.Body>
          <BaseTable
            data={groups || []}
            columns={columns}
            isFetching={isLoading}
            isError={isError}
            emptyText={t("No tax groups assigned.")}
          />
        </Card.Body>
      </Card>

      {/* Add Tax-Free Group Modal */}
      {showCreateModal && (
        <BaseModal bodyClassName="aa-panel"
          show={showCreateModal}
          onHide={() => setShowCreateModal(false)}
          size={ModalSize.medium}
          title={
            <div className="h5 text-primary d-flex align-items-center gap-2 mb-0">
              <Users2 size={18} />
              {t("Add Tax-Free Group")}
            </div>
          }
          footer={
            <>
              <Button
                variant="secondary"
                onClick={() => setShowCreateModal(false)}
              >
                {t("Cancel")}
              </Button>
              <Button
                variant="primary"
                disabled={!newGroupName.trim() || groupActions.isCreating}
                onClick={() => groupActions.create({ name: newGroupName, groupIds: selectedAuthGroupIds })}
              >
                {groupActions.isCreating && <Spinner size="sm" animation="border" className="me-1" />}
                {t("Create")}
              </Button>
            </>
          }
        >
          <Form.Group className="mb-3">
            <Form.Label>{t("Group Name")}</Form.Label>
            <Form.Control
              type="text"
              placeholder={t("e.g. Leadership, Logistics")}
              value={newGroupName}
              onChange={(e) => setNewGroupName(e.target.value)}
              className="bg-dark text-light border-secondary"
              autoFocus
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>{t("Select Auth Groups")}</Form.Label>
            <Form.Control
              type="text"
              placeholder={t("Search groups…")}
              value={authGroupSearch}
              onChange={(e) => setAuthGroupSearch(e.target.value)}
              size="sm"
              className="bg-dark text-light border-secondary mb-2"
            />
            <div
              className="p-2 aa-panel-light border border-secondary rounded overflow-auto aa-scroll-list"
            >
              {availableLoading ? (
                <div className="text-center py-3">
                  <Spinner size="sm" animation="border" className="text-primary" />
                </div>
              ) : filteredAvailableGroups.length === 0 ? (
                <div className="text-muted small text-center py-2">
                  {t("No auth groups found.")}
                </div>
              ) : (
                filteredAvailableGroups.map((g) => {
                  const isChecked = selectedAuthGroupIds.includes(g.id);
                  return (
                    <Form.Check
                      key={g.id}
                      type="checkbox"
                      id={`auth-group-${g.id}`}
                      label={g.name}
                      checked={isChecked}
                      onChange={() => toggleAuthGroup(g.id)}
                      className="mb-1"
                    />
                  );
                })
              )}
            </div>
            <Form.Text className="text-muted">
              {t(
                "Members belonging to any selected group will be exempt from taxes.",
              )}
            </Form.Text>
          </Form.Group>
        </BaseModal>
      )}

      {/* Delete Group Confirmation Modal */}
      {groupToDelete && (
        <BaseModal bodyClassName="aa-panel"
          show={!!groupToDelete}
          onHide={() => setGroupToDelete(null)}
          size={ModalSize.medium}
          title={
            <div className="h5 text-danger d-flex align-items-center gap-2 mb-0">
              <Trash2 size={18} />
              {t("Delete Tax-Free Group")}
            </div>
          }
          footer={
            <>
              <Button
                variant="secondary"
                onClick={() => setGroupToDelete(null)}
              >
                {t("Cancel")}
              </Button>
              <Button
                variant="danger"
                disabled={groupActions.isRemoving}
                onClick={() => {
                  if (groupToDelete.id) {
                    groupActions.remove({
                      groupPk: groupToDelete.id,
                      comment: deleteComment.trim() || t("Deleted via Tax System"),
                    });
                  }
                }}
              >
                {groupActions.isRemoving && <Spinner size="sm" animation="border" className="me-1" />}
                {t("Confirm Delete")}
              </Button>
            </>
          }
        >
          <p>
            {t("Are you sure you want to delete:")}{" "}
            <strong>{groupToDelete.name}</strong>?
          </p>
          <Form.Group className="mb-3">
            <Form.Label>{t("Reason / Comment")}</Form.Label>
            <Form.Control
              as="textarea"
              rows={2}
              value={deleteComment}
              onChange={(e) => setDeleteComment(e.target.value)}
              placeholder={t("Reason for deletion…")}
              className="bg-dark text-light border-secondary"
            />
          </Form.Group>
        </BaseModal>
      )}
    </div>
  );
}

export default GroupsTab;
